RRB.load({"id": "ntpc-full-7", "exam": "ntpc", "label": "NTPC UG full mock 7 (100 Q)", "questions": [{"s": "General Awareness", "t": "Geography", "q": "Kolleru, a large freshwater lake between the deltas of the Godavari and the Krishna, is in which state?", "o": ["Andhra Pradesh", "Telangana", "Odisha", "Tamil Nadu"], "a": 0, "e": "Kolleru Lake lies in Eluru district of Andhra Pradesh and is a Ramsar wetland.", "qh": "गोदावरी और कृष्णा के डेल्टा के बीच का बड़ा मीठे पानी का कोल्लेरु झील किस राज्य में है?", "oh": ["आंध्र प्रदेश", "तेलंगाना", "ओडिशा", "तमिलनाडु"], "eh": "कोल्लेरु झील आंध्र प्रदेश के एलुरु ज़िले में है और रामसर स्थल है।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "Which Article of the Constitution asks the State to try to secure a Uniform Civil Code for all citizens?", "o": ["Article 44", "Article 45", "Article 47", "Article 40"], "a": 0, "e": "Article 44 (a Directive Principle) deals with a Uniform Civil Code; Article 45 is early childhood care and Article 47 is nutrition and public health.", "qh": "संविधान का कौन-सा अनुच्छेद राज्य से सभी नागरिकों के लिए समान नागरिक संहिता लाने का प्रयास करने को कहता है?", "oh": ["अनुच्छेद 44", "अनुच्छेद 45", "अनुच्छेद 47", "अनुच्छेद 40"], "eh": "अनुच्छेद 44 (नीति निदेशक तत्व) समान नागरिक संहिता का है; अनुच्छेद 45 बचपन की देखभाल और 47 पोषण व जन स्वास्थ्य का है।", "level": "easy"}, {"s": "General Awareness", "t": "History", "q": "Who was the first woman President of the Indian National Congress?", "o": ["Sarojini Naidu", "Indira Gandhi", "Nellie Sengupta", "Annie Besant"], "a": 3, "e": "Annie Besant presided over the Calcutta session of 1917; Sarojini Naidu was the first Indian woman President (1925).", "qh": "भारतीय राष्ट्रीय कांग्रेस की पहली महिला अध्यक्ष कौन थीं?", "oh": ["सरोजिनी नायडू", "इंदिरा गांधी", "नेली सेनगुप्ता", "एनी बेसेंट"], "eh": "एनी बेसेंट ने 1917 के कलकत्ता अधिवेशन की अध्यक्षता की; सरोजिनी नायडू पहली भारतीय महिला अध्यक्ष (1925) थीं।", "level": "tough"}, {"s": "General Awareness", "t": "Sports", "q": "At the Milano Cortina 2026 Winter Olympics, Arif Mohammad Khan recorded India's best-ever finish in men's slalom. What was his position?", "o": ["45th", "28th", "49th", "39th"], "a": 3, "e": "Arif Khan finished 39th in men's slalom at Bormio on 16 February 2026 (Games: 6–22 February 2026, Italy), beating Kishore Rai's 49th place at Calgary 1988.", "qh": "मिलानो कोर्टिना 2026 शीतकालीन ओलंपिक में आरिफ़ मोहम्मद ख़ान ने पुरुष स्लैलम में भारत का अब तक का सबसे अच्छा स्थान हासिल किया। उनका स्थान क्या था?", "oh": ["45वाँ", "28वाँ", "49वाँ", "39वाँ"], "eh": "आरिफ़ ख़ान 16 फ़रवरी 2026 को बोर्मियो में पुरुष स्लैलम में 39वें स्थान पर रहे (खेल: 6–22 फ़रवरी 2026, इटली)। इससे पहले सबसे अच्छा स्थान कैलगरी 1988 में किशोर राय का 49वाँ था।", "level": "tough"}, {"s": "General Awareness", "t": "General Science", "q": "A rainbow is formed mainly due to which of these?", "o": ["Dispersion of sunlight by water droplets", "Reflection of light by clouds", "Scattering of light by dust", "Diffraction of light by air"], "a": 0, "e": "Raindrops refract, internally reflect and disperse sunlight into its seven colours.", "qh": "इंद्रधनुष मुख्य रूप से किस कारण बनता है?", "oh": ["पानी की बूंदों द्वारा सूर्य के प्रकाश का विक्षेपण (डिस्पर्शन)", "बादलों द्वारा प्रकाश का परावर्तन", "धूल द्वारा प्रकाश का प्रकीर्णन", "हवा द्वारा प्रकाश का विवर्तन"], "eh": "बारिश की बूंदें सूर्य के प्रकाश का अपवर्तन, आंतरिक परावर्तन और विक्षेपण करके उसे सात रंगों में बाँट देती हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The quorum needed to hold a sitting of either House of Parliament is:", "o": ["One-third of the members present", "One-tenth of the total number of members of the House", "Half of the total members", "One-fourth of the total members"], "a": 1, "e": "Article 100(3) fixes the quorum at one-tenth of the total number of members of each House.", "qh": "संसद के किसी भी सदन की बैठक के लिए ज़रूरी कोरम (गणपूर्ति) कितना है?", "oh": ["उपस्थित सदस्यों का एक-तिहाई", "सदन के कुल सदस्यों का दसवाँ भाग", "कुल सदस्यों का आधा", "कुल सदस्यों का एक-चौथाई"], "eh": "अनुच्छेद 100(3) के अनुसार हर सदन का कोरम उसके कुल सदस्यों का दसवाँ भाग है।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "The Ilbert Bill controversy (1883) took place during the tenure of which Viceroy?", "o": ["Lord Lytton", "Lord Curzon", "Lord Ripon", "Lord Dufferin"], "a": 2, "e": "Under Lord Ripon, the Ilbert Bill sought to let Indian judges try Europeans, leading to a European backlash.", "qh": "इल्बर्ट बिल विवाद (1883) किस वायसराय के कार्यकाल में हुआ?", "oh": ["लॉर्ड लिटन", "लॉर्ड कर्ज़न", "लॉर्ड रिपन", "लॉर्ड डफ़रिन"], "eh": "लॉर्ड रिपन के समय इल्बर्ट बिल भारतीय जजों को यूरोपीय लोगों के मुकदमे सुनने का अधिकार देना चाहता था, जिसका यूरोपियों ने विरोध किया।", "level": "tough"}, {"s": "General Awareness", "t": "Railways", "q": "Where is the headquarters of the Northern Railway zone?", "o": ["Lucknow", "Prayagraj", "New Delhi (Baroda House)", "Jaipur"], "a": 2, "e": "Northern Railway is headquartered at Baroda House, New Delhi; Prayagraj is the HQ of North Central Railway and Jaipur of North Western Railway.", "qh": "उत्तर रेलवे ज़ोन का मुख्यालय कहाँ है?", "oh": ["लखनऊ", "प्रयागराज", "नई दिल्ली (बड़ौदा हाउस)", "जयपुर"], "eh": "उत्तर रेलवे का मुख्यालय नई दिल्ली के बड़ौदा हाउस में है; प्रयागराज उत्तर मध्य रेलवे और जयपुर उत्तर पश्चिम रेलवे का मुख्यालय है।", "level": "medium"}, {"s": "General Awareness", "t": "Awards", "q": "The Pritzker Architecture Prize 2026 was awarded to Smiljan Radić Clarke, an architect from which country?", "o": ["Chile", "Spain", "Japan", "Mexico"], "a": 0, "e": "Chilean architect Smiljan Radić Clarke of Santiago became the 55th Pritzker laureate in 2026.", "qh": "2026 का प्रित्ज़कर आर्किटेक्चर पुरस्कार स्मिल्जान रादिच क्लार्क को मिला। वे किस देश के वास्तुकार हैं?", "oh": ["चिली", "स्पेन", "जापान", "मेक्सिको"], "eh": "सैंटियागो के चिली वास्तुकार स्मिल्जान रादिच क्लार्क 2026 में प्रित्ज़कर पाने वाले 55वें व्यक्ति बने।", "level": "tough"}, {"s": "General Awareness", "t": "Computer", "q": "In computer networks, a 'firewall' is mainly used to:", "o": ["Cool the processor", "Increase internet speed", "Store backup files", "Block unauthorised access to or from a network"], "a": 3, "e": "A firewall checks network traffic and blocks connections that break security rules.", "qh": "कंप्यूटर नेटवर्क में 'फ़ायरवॉल' मुख्य रूप से किसलिए इस्तेमाल होता है?", "oh": ["प्रोसेसर को ठंडा करने के लिए", "इंटरनेट की रफ़्तार बढ़ाने के लिए", "बैकअप फ़ाइलें रखने के लिए", "नेटवर्क में या उससे बिना अनुमति की पहुँच रोकने के लिए"], "eh": "फ़ायरवॉल नेटवर्क ट्रैफ़िक जाँचता है और सुरक्षा नियम तोड़ने वाले कनेक्शन रोक देता है।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The words 'Socialist' and 'Secular' were added to the Preamble by which Constitutional Amendment?", "o": ["44th Amendment, 1978", "24th Amendment, 1971", "42nd Amendment, 1976", "52nd Amendment, 1985"], "a": 2, "e": "The 42nd Amendment (1976) added 'Socialist', 'Secular' and 'Integrity' to the Preamble.", "qh": "प्रस्तावना में 'समाजवादी' और 'पंथनिरपेक्ष' शब्द किस संविधान संशोधन से जोड़े गए?", "oh": ["44वाँ संशोधन, 1978", "24वाँ संशोधन, 1971", "42वाँ संशोधन, 1976", "52वाँ संशोधन, 1985"], "eh": "42वें संशोधन (1976) ने प्रस्तावना में 'समाजवादी', 'पंथनिरपेक्ष' और 'अखंडता' शब्द जोड़े।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Who discovered penicillin, the first widely used antibiotic?", "o": ["Louis Pasteur", "Edward Jenner", "Robert Koch", "Alexander Fleming"], "a": 3, "e": "Alexander Fleming discovered penicillin from Penicillium mould in 1928.", "qh": "पहला बड़े पैमाने पर इस्तेमाल हुआ एंटीबायोटिक पेनिसिलिन किसने खोजा?", "oh": ["लुई पाश्चर", "एडवर्ड जेनर", "रॉबर्ट कोच", "अलेक्ज़ेंडर फ़्लेमिंग"], "eh": "अलेक्ज़ेंडर फ़्लेमिंग ने 1928 में पेनिसिलियम फफूंद से पेनिसिलिन खोजा।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Yakshagana, a traditional dance-drama form, belongs to which state?", "o": ["Kerala", "Andhra Pradesh", "Karnataka", "Maharashtra"], "a": 2, "e": "Yakshagana combines dance, music and dialogue and is popular in coastal Karnataka.", "qh": "पारंपरिक नृत्य-नाट्य यक्षगान किस राज्य का है?", "oh": ["केरल", "आंध्र प्रदेश", "कर्नाटक", "महाराष्ट्र"], "eh": "यक्षगान में नृत्य, संगीत और संवाद होते हैं और यह तटीय कर्नाटक में लोकप्रिय है।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "MGNREGA guarantees how many days of wage employment in a financial year to every rural household?", "o": ["100 days", "150 days", "120 days", "90 days"], "a": 0, "e": "The Mahatma Gandhi National Rural Employment Guarantee Act, 2005 guarantees 100 days of unskilled manual work per rural household each year.", "qh": "मनरेगा हर ग्रामीण परिवार को एक वित्त वर्ष में कितने दिन के मज़दूरी वाले काम की गारंटी देता है?", "oh": ["100 दिन", "150 दिन", "120 दिन", "90 दिन"], "eh": "महात्मा गांधी राष्ट्रीय ग्रामीण रोज़गार गारंटी अधिनियम, 2005 हर ग्रामीण परिवार को साल में 100 दिन के अकुशल शारीरिक काम की गारंटी देता है।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "Who was the founder of the Mughal Empire in India?", "o": ["Akbar", "Babur", "Humayun", "Sher Shah Suri"], "a": 1, "e": "Babur founded the Mughal Empire after defeating Ibrahim Lodi at the First Battle of Panipat (1526).", "qh": "भारत में मुग़ल साम्राज्य का संस्थापक कौन था?", "oh": ["अकबर", "बाबर", "हुमायूँ", "शेरशाह सूरी"], "eh": "बाबर ने पानीपत की पहली लड़ाई (1526) में इब्राहिम लोदी को हराकर मुग़ल साम्राज्य की नींव रखी।", "level": "easy"}, {"s": "General Awareness", "t": "Science & Tech", "q": "Which was India's first satellite, launched in 1975?", "o": ["Aryabhata", "Bhaskara", "Rohini", "INSAT-1A"], "a": 0, "e": "Aryabhata was launched on 19 April 1975 from the Soviet Union.", "qh": "भारत का पहला उपग्रह कौन-सा था, जो 1975 में छोड़ा गया?", "oh": ["आर्यभट", "भास्कर", "रोहिणी", "इनसैट-1A"], "eh": "आर्यभट 19 अप्रैल 1975 को सोवियत संघ से छोड़ा गया था।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "'Dry ice' is the solid form of:", "o": ["Carbon dioxide", "Water", "Nitrogen", "Ammonia"], "a": 0, "e": "Solid CO₂ (dry ice) turns directly into gas (sublimes) at about −78 °C.", "qh": "'शुष्क बर्फ़' (ड्राई आइस) किसका ठोस रूप है?", "oh": ["कार्बन डाइऑक्साइड", "पानी", "नाइट्रोजन", "अमोनिया"], "eh": "ठोस CO₂ (ड्राई आइस) लगभग −78 °C पर सीधे गैस बन जाती है (ऊर्ध्वपातन)।", "level": "easy"}, {"s": "General Awareness", "t": "Static GK", "q": "Who wrote the autobiography 'Wings of Fire'?", "o": ["Jawaharlal Nehru", "Mahatma Gandhi", "A. P. J. Abdul Kalam", "Vikram Sarabhai"], "a": 2, "e": "'Wings of Fire' (1999) is Dr A. P. J. Abdul Kalam's autobiography, written with Arun Tiwari.", "qh": "आत्मकथा 'विंग्स ऑफ़ फ़ायर' किसने लिखी?", "oh": ["जवाहरलाल नेहरू", "महात्मा गांधी", "ए. पी. जे. अब्दुल कलाम", "विक्रम साराभाई"], "eh": "'विंग्स ऑफ़ फ़ायर' (1999) डॉ. ए. पी. जे. अब्दुल कलाम की आत्मकथा है, जो अरुण तिवारी के साथ लिखी गई।", "level": "easy"}, {"s": "General Awareness", "t": "Static GK", "q": "Who is known as the 'Father of the Indian Constitution'?", "o": ["Jawaharlal Nehru", "Rajendra Prasad", "B. R. Ambedkar", "Sardar Patel"], "a": 2, "e": "Dr B. R. Ambedkar chaired the Drafting Committee of the Constituent Assembly.", "qh": "'भारतीय संविधान के जनक' किसे कहा जाता है?", "oh": ["जवाहरलाल नेहरू", "राजेंद्र प्रसाद", "बी. आर. आंबेडकर", "सरदार पटेल"], "eh": "डॉ. बी. आर. आंबेडकर संविधान सभा की प्रारूप समिति के अध्यक्ष थे।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Which of these is a cold desert in India?", "o": ["Thar", "Ladakh", "Rann of Kutch", "Bundelkhand"], "a": 1, "e": "Ladakh is a high-altitude cold desert in the rain shadow of the Himalaya; the Thar is a hot desert.", "qh": "इनमें से कौन-सा भारत का ठंडा मरुस्थल है?", "oh": ["थार", "लद्दाख", "कच्छ का रण", "बुंदेलखंड"], "eh": "लद्दाख हिमालय की वर्षा-छाया में ऊँचाई पर स्थित ठंडा मरुस्थल है; थार गर्म मरुस्थल है।", "level": "tough"}, {"s": "General Awareness", "t": "Geography", "q": "Which ocean lies to the south of India?", "o": ["Pacific Ocean", "Atlantic Ocean", "Arctic Ocean", "Indian Ocean"], "a": 3, "e": "The Indian Ocean lies south of India, with the Arabian Sea to the west and the Bay of Bengal to the east.", "qh": "भारत के दक्षिण में कौन-सा महासागर है?", "oh": ["प्रशांत महासागर", "अटलांटिक महासागर", "आर्कटिक महासागर", "हिंद महासागर"], "eh": "भारत के दक्षिण में हिंद महासागर, पश्चिम में अरब सागर और पूर्व में बंगाल की खाड़ी है।", "level": "easy"}, {"s": "General Awareness", "t": "Economy", "q": "In the Global Hunger Index 2026, India was ranked:", "o": ["105th out of 127 countries", "100th out of 122 countries", "111th out of 125 countries", "94th out of 107 countries"], "a": 1, "e": "GHI 2026 ranked India 100th of 122 countries with a score of 24.1 ('serious').", "qh": "ग्लोबल हंगर इंडेक्स 2026 में भारत का स्थान क्या था?", "oh": ["127 देशों में 105वाँ", "122 देशों में 100वाँ", "125 देशों में 111वाँ", "107 देशों में 94वाँ"], "eh": "GHI 2026 में भारत 122 देशों में 100वें स्थान पर रहा (स्कोर 24.1, 'गंभीर' श्रेणी)।", "level": "tough"}, {"s": "General Awareness", "t": "Computer", "q": "What does 'HTML' stand for?", "o": ["High Transfer Machine Language", "HyperText Making Link", "Home Tool Markup Language", "HyperText Markup Language"], "a": 3, "e": "HTML is the standard language used to create web pages.", "qh": "'HTML' का पूरा नाम क्या है?", "oh": ["हाई ट्रांसफ़र मशीन लैंग्वेज", "हाइपरटेक्स्ट मेकिंग लिंक", "होम टूल मार्कअप लैंग्वेज", "हाइपरटेक्स्ट मार्कअप लैंग्वेज"], "eh": "HTML वेब पेज बनाने की मानक भाषा है।", "level": "easy"}, {"s": "General Awareness", "t": "Art & Culture", "q": "The Brihadeeswarar Temple at Thanjavur was built by which ruler?", "o": ["Rajendra Chola I", "Krishnadevaraya", "Narasimhavarman I", "Rajaraja Chola I"], "a": 3, "e": "Rajaraja Chola I completed the Brihadeeswarar (Peruvudaiyar) Temple around 1010 CE; it is part of the 'Great Living Chola Temples' World Heritage Site.", "qh": "तंजावुर का बृहदेश्वर मंदिर किस शासक ने बनवाया?", "oh": ["राजेंद्र चोल प्रथम", "कृष्णदेवराय", "नरसिंहवर्मन प्रथम", "राजराज चोल प्रथम"], "eh": "राजराज चोल प्रथम ने लगभग 1010 ई. में बृहदेश्वर मंदिर पूरा करवाया; यह 'महान जीवित चोल मंदिर' विश्व धरोहर का हिस्सा है।", "level": "tough"}, {"s": "General Awareness", "t": "Economy", "q": "India and the European Union announced the conclusion of their Free Trade Agreement negotiations at the 16th India–EU Summit held in which city in January 2026?", "o": ["Brussels", "New Delhi", "Mumbai", "Strasbourg"], "a": 1, "e": "The 16th EU–India Summit in New Delhi on 27 January 2026 announced the conclusion of FTA negotiations.", "qh": "जनवरी 2026 में भारत और यूरोपीय संघ ने 16वें भारत–EU शिखर सम्मेलन में मुक्त व्यापार समझौते की बातचीत पूरी होने की घोषणा की। यह सम्मेलन किस शहर में हुआ?", "oh": ["ब्रसेल्स", "नई दिल्ली", "मुंबई", "स्ट्रासबर्ग"], "eh": "27 जनवरी 2026 को नई दिल्ली में 16वें EU–भारत शिखर सम्मेलन में FTA वार्ता पूरी होने की घोषणा हुई।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The Komagata Maru incident of 1914 involved a ship carrying Indian passengers that was refused entry by:", "o": ["Australia", "South Africa", "USA", "Canada"], "a": 3, "e": "The Komagata Maru carried 376 mostly Punjabi passengers to Vancouver in 1914; Canada refused them entry, and many were killed at Budge Budge on return.", "qh": "1914 की कोमागाटा मारू घटना में भारतीय यात्रियों वाले एक जहाज़ को किस देश ने प्रवेश नहीं दिया?", "oh": ["ऑस्ट्रेलिया", "दक्षिण अफ़्रीका", "अमेरिका", "कनाडा"], "eh": "1914 में कोमागाटा मारू 376 यात्रियों (ज़्यादातर पंजाबी) को लेकर वैंकूवर पहुँचा; कनाडा ने उन्हें उतरने नहीं दिया और लौटने पर बज बज में कई लोग मारे गए।", "level": "medium"}, {"s": "General Awareness", "t": "Sports", "q": "Who won the men's Ballon d'Or 2026, presented in London on 26 October 2026?", "o": ["Lamine Yamal", "Kylian Mbappé", "Harry Kane", "Rodri"], "a": 2, "e": "England striker Harry Kane won the men's Ballon d'Or and Alexia Putellas the women's award at the London Palladium.", "qh": "26 अक्टूबर 2026 को लंदन में दिया गया पुरुष बैलन डी'ओर 2026 किसने जीता?", "oh": ["लामिन यामल", "किलियन एम्बाप्पे", "हैरी केन", "रोड्री"], "eh": "इंग्लैंड के स्ट्राइकर हैरी केन ने पुरुष और एलेक्सिया पुतेयास ने महिला बैलन डी'ओर जीता।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The Non-Cooperation Movement was called off in 1922 after which incident?", "o": ["Jallianwala Bagh", "Kakori", "Chauri Chaura", "Champaran"], "a": 2, "e": "After a mob burnt a police station at Chauri Chaura (Gorakhpur) in February 1922, Gandhiji withdrew the movement.", "qh": "1922 में असहयोग आंदोलन किस घटना के बाद वापस लिया गया?", "oh": ["जलियाँवाला बाग", "काकोरी", "चौरी चौरा", "चंपारण"], "eh": "फ़रवरी 1922 में चौरी चौरा (गोरखपुर) में भीड़ ने थाना जला दिया, जिसके बाद गांधीजी ने आंदोलन वापस ले लिया।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "In April 2026, the Constitution (131st Amendment) Bill, linked to delimitation and women's reservation, failed in the Lok Sabha because:", "o": ["It did not get the required two-thirds majority of members present and voting", "The President returned it", "The Rajya Sabha rejected it first", "The Supreme Court stayed it"], "a": 0, "e": "On 17 April 2026 the Bill got 298 votes for and 230 against — short of the special majority under Article 368.", "qh": "अप्रैल 2026 में परिसीमन और महिला आरक्षण से जुड़ा संविधान (131वाँ संशोधन) विधेयक लोकसभा में गिर गया, क्योंकि:", "oh": ["इसे उपस्थित और मतदान करने वाले सदस्यों का ज़रूरी दो-तिहाई बहुमत नहीं मिला", "राष्ट्रपति ने इसे लौटा दिया", "राज्यसभा ने इसे पहले ही खारिज कर दिया", "सुप्रीम कोर्ट ने इस पर रोक लगा दी"], "eh": "17 अप्रैल 2026 को विधेयक के पक्ष में 298 और विपक्ष में 230 वोट पड़े — अनुच्छेद 368 के विशेष बहुमत से कम।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "In which year was the National Human Rights Commission (NHRC) of India set up?", "o": ["1986", "2001", "1978", "1993"], "a": 3, "e": "The NHRC was set up on 12 October 1993 under the Protection of Human Rights Act, 1993.", "qh": "भारत का राष्ट्रीय मानवाधिकार आयोग (NHRC) किस साल बना?", "oh": ["1986", "2001", "1978", "1993"], "eh": "NHRC 12 अक्टूबर 1993 को मानवाधिकार संरक्षण अधिनियम, 1993 के तहत बना।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Ustad Bismillah Khan was famous for playing which instrument?", "o": ["Shehnai", "Sitar", "Sarod", "Tabla"], "a": 0, "e": "Bharat Ratna Ustad Bismillah Khan of Varanasi made the shehnai famous worldwide.", "qh": "उस्ताद बिस्मिल्लाह ख़ान किस वाद्य यंत्र को बजाने के लिए प्रसिद्ध थे?", "oh": ["शहनाई", "सितार", "सरोद", "तबला"], "eh": "वाराणसी के भारत रत्न उस्ताद बिस्मिल्लाह ख़ान ने शहनाई को दुनिया भर में प्रसिद्ध किया।", "level": "tough"}, {"s": "General Awareness", "t": "Awards", "q": "The Param Vir Chakra is India's highest award for:", "o": ["Peacetime bravery", "Literature", "Public service", "Gallantry during war"], "a": 3, "e": "The Param Vir Chakra is the highest wartime gallantry award; the Ashoka Chakra is the highest peacetime gallantry award.", "qh": "परमवीर चक्र भारत का सर्वोच्च पुरस्कार किसके लिए है?", "oh": ["शांति के समय वीरता", "साहित्य", "लोक सेवा", "युद्ध के समय वीरता"], "eh": "परमवीर चक्र युद्धकाल का सर्वोच्च वीरता पुरस्कार है; शांतिकाल का सर्वोच्च वीरता पुरस्कार अशोक चक्र है।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Which river forms the Jog Falls in Karnataka?", "o": ["Sharavathi", "Kaveri", "Tungabhadra", "Krishna"], "a": 0, "e": "Jog Falls (about 253 m) is formed by the Sharavathi river in Shivamogga district.", "qh": "कर्नाटक का जोग जलप्रपात किस नदी से बनता है?", "oh": ["शरावती", "कावेरी", "तुंगभद्रा", "कृष्णा"], "eh": "जोग जलप्रपात (लगभग 253 m) शिवमोग्गा ज़िले में शरावती नदी से बनता है।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Which state is the largest producer of tea in India?", "o": ["Kerala", "Assam", "West Bengal", "Tamil Nadu"], "a": 1, "e": "Assam produces more than half of India's tea.", "qh": "भारत में चाय का सबसे बड़ा उत्पादक राज्य कौन-सा है?", "oh": ["केरल", "असम", "पश्चिम बंगाल", "तमिलनाडु"], "eh": "भारत की आधी से ज़्यादा चाय असम में पैदा होती है।", "level": "easy"}, {"s": "General Awareness", "t": "Economy", "q": "The BSE Sensex is a stock market index made up of how many companies?", "o": ["50", "30", "100", "40"], "a": 1, "e": "The Sensex tracks 30 large, actively traded companies on the BSE; the NSE's Nifty has 50.", "qh": "BSE सेंसेक्स कितनी कंपनियों से बना शेयर बाज़ार सूचकांक है?", "oh": ["50", "30", "100", "40"], "eh": "सेंसेक्स BSE की 30 बड़ी, सक्रिय रूप से कारोबार वाली कंपनियों पर आधारित है; NSE के निफ़्टी में 50 हैं।", "level": "easy"}, {"s": "General Awareness", "t": "Science & Tech", "q": "NASA's Artemis II, launched on 1 April 2026, was the first crewed mission in over 50 years to:", "o": ["Fly around the Moon", "Land on Mars", "Land near the Moon's south pole", "Dock with a lunar space station"], "a": 0, "e": "Artemis II carried four astronauts (Wiseman, Glover, Koch and Canada's Jeremy Hansen) on a lunar flyby on 6 April and splashed down on 10 April 2026.", "qh": "1 अप्रैल 2026 को लॉन्च हुआ नासा का आर्टेमिस II, 50 साल से ज़्यादा समय में ऐसा पहला मानवयुक्त मिशन था जिसने:", "oh": ["चंद्रमा का चक्कर लगाया", "मंगल पर लैंडिंग की", "चंद्रमा के दक्षिणी ध्रुव के पास लैंडिंग की", "चंद्र अंतरिक्ष स्टेशन से जुड़ाव किया"], "eh": "आर्टेमिस II चार अंतरिक्ष यात्रियों (वाइज़मैन, ग्लोवर, कोच और कनाडा के जेरेमी हैनसन) को लेकर 6 अप्रैल को चंद्रमा के पास से गुज़रा और 10 अप्रैल 2026 को समुद्र में उतरा।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Which Chinese Buddhist pilgrim visited India during the reign of Harshavardhana?", "o": ["Fa-Hien (Faxian)", "I-Tsing (Yijing)", "Sung Yun", "Hiuen Tsang (Xuanzang)"], "a": 3, "e": "Hiuen Tsang stayed in India c. 630–645 CE, studied at Nalanda and attended Harsha's assemblies; Fa-Hien came under Chandragupta II.", "qh": "हर्षवर्धन के शासनकाल में कौन-सा चीनी बौद्ध यात्री भारत आया था?", "oh": ["फ़ाह्यान (फ़ाक्सियान)", "इत्सिंग (यीजिंग)", "सुंग युन", "ह्वेनसांग (ज़ुआनज़ांग)"], "eh": "ह्वेनसांग लगभग 630–645 ई. में भारत में रहा, नालंदा में पढ़ा और हर्ष की सभाओं में गया; फ़ाह्यान चंद्रगुप्त द्वितीय के समय आया था।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who was sworn in as Prime Minister of Hungary on 9 May 2026, ending Viktor Orbán's 16-year rule?", "o": ["Viktor Orbán", "Katalin Novák", "Gergely Karácsony", "Péter Magyar"], "a": 3, "e": "Péter Magyar of the Tisza party became Prime Minister after a landslide election win.", "qh": "9 मई 2026 को विक्टर ओरबान के 16 साल के शासन को खत्म करते हुए हंगरी के प्रधानमंत्री के रूप में किसने शपथ ली?", "oh": ["विक्टर ओरबान", "कातालिन नोवाक", "गेरगेई कारात्सोन्यी", "पीटर मग्यार"], "eh": "तिसा पार्टी के पीटर मग्यार भारी जीत के बाद प्रधानमंत्री बने।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Haemoglobin, the red pigment in blood that carries oxygen, contains which metal?", "o": ["Iron", "Magnesium", "Copper", "Zinc"], "a": 0, "e": "Each haem group in haemoglobin has an iron (Fe²⁺) atom that binds oxygen. (Chlorophyll contains magnesium.)", "qh": "रक्त में ऑक्सीजन ले जाने वाले लाल वर्णक हीमोग्लोबिन में कौन-सी धातु होती है?", "oh": ["लोहा", "मैग्नीशियम", "तांबा", "जस्ता"], "eh": "हीमोग्लोबिन के हर हीम समूह में लोहे (Fe²⁺) का एक परमाणु होता है जो ऑक्सीजन से जुड़ता है। (क्लोरोफ़िल में मैग्नीशियम होता है।)", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "The 'Comptroller and Auditor General of India' is appointed under which Article?", "o": ["Article 76", "Article 124", "Article 280", "Article 148"], "a": 3, "e": "Article 148 provides for the CAG; Article 76 is the Attorney General, 124 the Supreme Court and 280 the Finance Commission.", "qh": "भारत के नियंत्रक एवं महालेखा परीक्षक (CAG) की नियुक्ति किस अनुच्छेद के तहत होती है?", "oh": ["अनुच्छेद 76", "अनुच्छेद 124", "अनुच्छेद 280", "अनुच्छेद 148"], "eh": "अनुच्छेद 148 CAG का है; 76 महान्यायवादी, 124 सुप्रीम कोर्ट और 280 वित्त आयोग का है।", "level": "tough"}, {"s": "Mathematics", "t": "Interest", "q": "What is the simple interest on ₹6,000 at 5% per annum for 2 years?", "o": ["₹300", "₹600", "₹6,600", "₹1,200"], "a": 1, "e": "SI = P × R × T/100 = 6000 × 5 × 2/100 = ₹600.", "qh": "₹6,000 पर 5% वार्षिक दर से 2 साल का साधारण ब्याज कितना होगा?", "oh": ["₹300", "₹600", "₹6,600", "₹1,200"], "eh": "साधारण ब्याज = P × R × T/100 = 6000 × 5 × 2/100 = ₹600।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A seller suffers a loss of 12% when he sells a mixer-grinder for ₹2,992. What should the selling price be to make a profit of 12%?", "o": ["₹3,858", "₹3,400", "₹3,808", "₹3,809"], "a": 2, "e": "CP = ₹2,992 × 100/88 = ₹3,400; required SP = ₹3,400 × 112/100 = ₹3,808.", "qh": "एक मिक्सर-ग्राइंडर ₹2,992 में बेचने पर विक्रेता को 12% हानि होती है। 12% लाभ कमाने के लिए विक्रय मूल्य क्या होना चाहिए?", "oh": ["₹3,858", "₹3,400", "₹3,808", "₹3,809"], "eh": "क्रय मूल्य = ₹2,992 × 100/88 = ₹3,400; ज़रूरी विक्रय मूल्य = ₹3,400 × 112/100 = ₹3,808।", "level": "tough"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 7 consecutive odd numbers is 33. What is the smallest of them?", "o": ["39", "27", "25", "40"], "a": 1, "e": "The average is the middle number 33; there are 3 numbers on each side with gap 2 → smallest = 27.", "qh": "7 लगातार विषम संख्याओं का औसत 33 है। उनमें सबसे छोटी संख्या कौन-सी है?", "oh": ["39", "27", "25", "40"], "eh": "औसत ही बीच वाली संख्या 33 है; दोनों ओर 3 संख्याएँ, अंतर 2 → उत्तर = 27।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "What is the smallest 3-digit number which, when divided by 8, 12 and 18, leaves a remainder of 2 in each case?", "o": ["144", "218", "146", "148"], "a": 2, "e": "LCM = 72. The required number is a multiple of 72 plus 2: 144 + 2 = 146.", "qh": "3 अंकों की वह सबसे छोटी संख्या कौन-सी है जिसे 8, 12 और 18 से भाग देने पर हर बार 2 शेष बचे?", "oh": ["144", "218", "146", "148"], "eh": "LCM = 72। चाहिए: 72 का गुणज + 2: 144 + 2 = 146।", "level": "medium"}, {"s": "Mathematics", "t": "Algebra", "q": "If a = 9, b = 11 and c = 5, what is the value of a² + b² + c² − ab − bc − ca?", "o": ["31", "28", "56", "227"], "a": 1, "e": "= ½[(a − b)² + (b − c)² + (c − a)²] = ½[4 + 36 + 16] = 28.", "qh": "अगर a = 9, b = 11 और c = 5 है, तो a² + b² + c² − ab − bc − ca का मान क्या है?", "oh": ["31", "28", "56", "227"], "eh": "= ½[(a − b)² + (b − c)² + (c − a)²] = ½[4 + 36 + 16] = 28।", "level": "easy"}, {"s": "Mathematics", "t": "Percentage", "q": "In an examination, a student who scores 35% marks fails by 20 marks, while another student who scores 48% marks gets 32 marks more than the pass marks. What are the maximum marks?", "o": ["450", "400", "320", "300"], "a": 1, "e": "(48 − 35)% of maximum = 20 + 32 = 52 → maximum = 52 × 100/13 = 400.", "qh": "एक परीक्षा में 35% अंक पाने वाला छात्र 20 अंकों से फ़ेल होता है, जबकि 48% अंक पाने वाले छात्र को पास अंकों से 32 अंक ज़्यादा मिलते हैं। पूरे अंक कितने हैं?", "oh": ["450", "400", "320", "300"], "eh": "पूरे अंकों का (48 − 35)% = 20 + 32 = 52 → पूरे अंक = 52 × 100/13 = 400।", "level": "medium"}, {"s": "Mathematics", "t": "Algebra", "q": "If x + 1/x = 6, what is the value of x³ + 1/x³?", "o": ["234", "216", "210", "198"], "a": 3, "e": "x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 216 − 18 = 198.", "qh": "अगर x + 1/x = 6 है, तो x³ + 1/x³ का मान क्या है?", "oh": ["234", "216", "210", "198"], "eh": "x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 216 − 18 = 198।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A shopkeeper gives a discount of 20% on the marked price of a water purifier and still makes a profit of 20%. If its cost price is ₹2,940, what is the marked price?", "o": ["₹4,116", "₹4,470", "₹4,410", "₹4,370"], "a": 2, "e": "SP = ₹2,940 × 120/100 = ₹3,528; MP = SP × 100/80 = ₹4,410.", "qh": "एक दुकानदार एक वॉटर प्यूरीफ़ायर के अंकित मूल्य पर 20% छूट देता है और फिर भी 20% लाभ कमाता है। अगर इसका क्रय मूल्य ₹2,940 है, तो अंकित मूल्य क्या है?", "oh": ["₹4,116", "₹4,470", "₹4,410", "₹4,370"], "eh": "विक्रय मूल्य = ₹2,940 × 120/100 = ₹3,528; अंकित मूल्य = विक्रय मूल्य × 100/80 = ₹4,410।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the volume of a cylinder with radius 14 cm and height 24 cm? (Take π = 22/7)", "o": ["14784 cm³", "22176 cm³", "29568 cm³", "14740 cm³"], "a": 0, "e": "πr²h = 22/7 × 14² × 24 = 14784 cm³.", "qh": "14 cm त्रिज्या और ऊँचाई 24 cm वाले बेलन का आयतन कितना है? (π = 22/7 लें)", "oh": ["14784 cm³", "22176 cm³", "29568 cm³", "14740 cm³"], "eh": "πr²h = 22/7 × 14² × 24 = 14784 cm³।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "An amount is divided among Ritu, Suresh and Sapna in the ratio 3 : 5 : 7. If Sapna gets ₹2,000 more than Ritu, what is Suresh's share?", "o": ["₹5,000", "₹1,500", "₹2,500", "₹3,000"], "a": 2, "e": "(7 − 3) parts = ₹2,000 → 1 part = ₹500; Suresh = 5 × ₹500 = ₹2,500.", "qh": "एक रकम को रितु, सुरेश और सपना में 3 : 5 : 7 के अनुपात में बाँटा गया। अगर सपना को रितु से ₹2,000 ज़्यादा मिलते हैं, तो सुरेश का हिस्सा कितना है?", "oh": ["₹5,000", "₹1,500", "₹2,500", "₹3,000"], "eh": "(7 − 3) भाग = ₹2,000 → 1 भाग = ₹500; सुरेश = 5 × ₹500 = ₹2,500।", "level": "medium"}, {"s": "Mathematics", "t": "Interest", "q": "The difference between compound interest and simple interest on a sum for 2 years at 5% per annum is ₹105. Find the sum.", "o": ["₹43,000", "₹42,000", "₹41,500", "₹2,100"], "a": 1, "e": "P(R/100)² = ₹105 → P = ₹105 × (100/5)² = ₹42,000.", "qh": "किसी राशि पर 5% वार्षिक दर से 2 साल के चक्रवृद्धि और साधारण ब्याज का अंतर ₹105 है। राशि बताइए।", "oh": ["₹43,000", "₹42,000", "₹41,500", "₹2,100"], "eh": "P(R/100)² = ₹105 → P = ₹105 × (100/5)² = ₹42,000।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "By selling 24 notebooks, a trader loses an amount equal to the selling price of 6 notebooks. What is his loss percentage?", "o": ["25%", "20%", "33 1/3%", "40%"], "a": 1, "e": "Loss = SP of 6, so CP of 24 = SP of 30. Loss % = 6/30 × 100 = 20%.", "qh": "24 कॉपियाँ बेचकर एक व्यापारी को 6 कॉपियाँ के विक्रय मूल्य के बराबर हानि होती है। उसका हानि प्रतिशत क्या है?", "oh": ["25%", "20%", "33 1/3%", "40%"], "eh": "हानि = 6 का विक्रय मूल्य, इसलिए 24 का क्रय मूल्य = 30 का विक्रय मूल्य। हानि % = 6/30 × 100 = 20%।", "level": "tough"}, {"s": "Mathematics", "t": "Time and Work", "q": "18 men working 8 hours a day can complete a work in 15 days. In how many days will 36 men working 12 hours a day complete the same work?", "o": ["7.5 days", "45 days", "3 days", "5 days"], "a": 3, "e": "M₁D₁H₁ = M₂D₂H₂ → 18 × 15 × 8 = 36 × D × 12 → D = 5 days.", "qh": "18 आदमी रोज़ 8 घंटे काम करके एक काम 15 दिन में पूरा करते हैं। 36 आदमी रोज़ 12 घंटे काम करके वही काम कितने दिन में पूरा करेंगे?", "oh": ["7.5 दिन", "45 दिन", "3 दिन", "5 दिन"], "eh": "M₁D₁H₁ = M₂D₂H₂ → 18 × 15 × 8 = 36 × D × 12 → D = 5 दिन।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Find the value of (2^5 × 2^5) ÷ (2^5 × 4²).", "o": ["2", "12", "3", "4"], "a": 0, "e": "4² = 2^4. Power = 5 + 5 − 5 − 4 = 1 → 2^1 = 2.", "qh": "(2^5 × 2^5) ÷ (2^5 × 4²) का मान ज्ञात कीजिए।", "oh": ["2", "12", "3", "4"], "eh": "4² = 2^4. घात = 5 + 5 − 5 − 4 = 1 → 2^1 = 2।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "What is the remainder when 392 × 265 is divided by 8?", "o": ["3", "1", "0", "2"], "a": 2, "e": "392 mod 8 = 0, 265 mod 8 = 1; 0 × 1 = 0; remainder = 0.", "qh": "392 × 265 को 8 से भाग देने पर शेषफल क्या होगा?", "oh": ["3", "1", "0", "2"], "eh": "392 का शेष 0, 265 का शेष 1; 0 × 1 = 0; शेषफल = 0।", "level": "tough"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A train 240 m long running at 36 km/h crosses a platform 360 m long. How many seconds does it take?", "o": ["24 seconds", "120 seconds", "60 seconds", "36 seconds"], "a": 2, "e": "Distance = 240 + 360 = 600 m; speed = 10 m/s; time = 600/10 = 60 s.", "qh": "240 m लंबी ट्रेन 36 km/h की रफ़्तार से 360 m लंबा प्लेटफ़ॉर्म पार करती है। इसमें कितने सेकंड लगते हैं?", "oh": ["24 सेकंड", "120 सेकंड", "60 सेकंड", "36 सेकंड"], "eh": "दूरी = 240 + 360 = 600 m; रफ़्तार = 10 m/s; समय = 600/10 = 60 सेकंड।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "A number is increased by 25%, then decreased by 25%, and then increased by 20%. The result is 2250. What was the original number?", "o": ["2250", "2000", "1900", "2200"], "a": 1, "e": "Original × 9/8 = 2250 → original = 2250 ÷ 9/8 = 2000.", "qh": "एक संख्या को पहले 25% बढ़ाया, फिर 25% घटाया, और फिर 20% बढ़ाया। नतीजा 2250 आया। मूल संख्या क्या थी?", "oh": ["2250", "2000", "1900", "2200"], "eh": "मूल संख्या × 9/8 = 2250 → मूल संख्या = 2250 ÷ 9/8 = 2000।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Deepak bought a second-hand refrigerator for ₹12,500 and spent ₹1,600 on repairs. He sold it for ₹15,510. What is his profit percentage?", "o": ["24 2/25%", "15%", "10%", "11 7/25%"], "a": 2, "e": "Total CP = ₹12,500 + ₹1,600 = ₹14,100; profit = ₹1,410; profit % = ₹1,410/₹14,100 × 100 = 10%.", "qh": "दीपक ने एक पुराना फ़्रिज ₹12,500 में खरीदा और ₹1,600 मरम्मत पर खर्च किए। उसने इसे ₹15,510 में बेचा। उसका लाभ प्रतिशत क्या है?", "oh": ["24 2/25%", "15%", "10%", "11 7/25%"], "eh": "कुल क्रय मूल्य = ₹12,500 + ₹1,600 = ₹14,100; लाभ = ₹1,410; लाभ % = ₹1,410/₹14,100 × 100 = 10%।", "level": "tough"}, {"s": "Mathematics", "t": "Geometry", "q": "What is the sum of the complement and the supplement of 54°?", "o": ["172°", "126°", "270°", "162°"], "a": 3, "e": "(90° − 54°) + (180° − 54°) = 162°.", "qh": "54° के पूरक कोण और संपूरक कोण का योग कितना है?", "oh": ["172°", "126°", "270°", "162°"], "eh": "(90° − 54°) + (180° − 54°) = 162°।", "level": "medium"}, {"s": "Mathematics", "t": "Trigonometry", "q": "Find the value of cot² 30° − sec 60° + sec² 45°.", "o": ["6", "5/2", "7/2", "3"], "a": 3, "e": "Put standard values: cot² 30° = 3, sec 60° = 2, sec² 45° = 2 → value = 3.", "qh": "cot² 30° − sec 60° + sec² 45° का मान ज्ञात कीजिए।", "oh": ["6", "5/2", "7/2", "3"], "eh": "मानक मान रखें: cot² 30° = 3, sec 60° = 2, sec² 45° = 2 → मान = 3।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "How many factors (divisors) does 180 have?", "o": ["18", "14", "6", "20"], "a": 0, "e": "180 = 2^2 × 3^2 × 5; number of factors = (2+1) × (2+1) × (1+1) = 18.", "qh": "180 के कितने गुणनखंड (भाजक) हैं?", "oh": ["18", "14", "6", "20"], "eh": "180 = 2^2 × 3^2 × 5; गुणनखंडों की संख्या = (2+1) × (2+1) × (1+1) = 18।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "A rectangular park is 40 m long and 30 m wide. A path 2 m wide runs all around it on the outside. What is the cost of paving the path at ₹50 per m²?", "o": ["₹14,300", "₹15,800", "₹14,800", "₹14,000"], "a": 2, "e": "Path area = (40+4)(30+4) − 40×30 = 296 m². Cost = 296 × 50 = ₹14,800.", "qh": "एक आयताकार पार्क 40 m लंबा और 30 m चौड़ा है। उसके चारों ओर बाहर की तरफ़ 2 m चौड़ा रास्ता है। ₹50 प्रति m² की दर से रास्ता बनवाने का खर्च कितना होगा?", "oh": ["₹14,300", "₹15,800", "₹14,800", "₹14,000"], "eh": "रास्ते का क्षेत्रफल = (40+4)(30+4) − 40×30 = 296 m²। खर्च = 296 × 50 = ₹14,800।", "level": "tough"}, {"s": "Mathematics", "t": "Ages", "q": "A father is 4 times as old as his son. The difference of their ages is 27 years. What is the father's age?", "o": ["36 years", "45 years", "9 years", "46 years"], "a": 0, "e": "4s − s = 27 → s = 9; father = 36 years.", "qh": "एक पिता की आयु उसके बेटे की आयु की 4 गुनी है। दोनों की आयु का अंतर 27 साल है। पिता की आयु कितनी है?", "oh": ["36 साल", "45 साल", "9 साल", "46 साल"], "eh": "4s − s = 27 → s = 9; पिता = 36 साल।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "Deepak starts a business with ₹45,000. After 8 months, Ajay joins with ₹50,000. At the end of the year the profit is ₹18,500. What is Ajay's share?", "o": ["₹13,500", "₹6,000", "₹7,000", "₹5,000"], "a": 3, "e": "Capital × months = 45000×12 : 50000×4 = 27 : 10. Share = 10/37 × ₹18,500 = ₹5,000.", "qh": "दीपक ₹45,000 से कारोबार शुरू करता है। 8 महीने बाद अजय ₹50,000 लेकर जुड़ता है। साल के आखिर में लाभ ₹18,500 है। अजय का हिस्सा कितना है?", "oh": ["₹13,500", "₹6,000", "₹7,000", "₹5,000"], "eh": "पूँजी × महीने = 45000×12 : 50000×4 = 27 : 10। हिस्सा = 10/37 × ₹18,500 = ₹5,000।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "The HCF of two numbers is 12 and their LCM is 756. If one of the numbers is 84, what is the other number?", "o": ["108", "63", "96", "120"], "a": 0, "e": "Product of numbers = HCF × LCM → other = 12 × 756/84 = 108.", "qh": "दो संख्याओं का HCF 12 और LCM 756 है। अगर एक संख्या 84 है, तो दूसरी संख्या क्या है?", "oh": ["108", "63", "96", "120"], "eh": "संख्याओं का गुणनफल = HCF × LCM → दूसरी = 12 × 756/84 = 108।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "A and B together can do a piece of work in 12 days, B and C together in 20 days, and C and A together in 15 days. In how many days can A, B and C together finish it?", "o": ["60 days", "20 days", "47/3 days", "10 days"], "a": 3, "e": "2(A + B + C) = 1/12 + 1/20 + 1/15 → A + B + C = 1/10 per day → 10 days.", "qh": "A और B मिलकर एक काम 12 दिन में, B और C मिलकर 20 दिन में, और C और A मिलकर 15 दिन में कर सकते हैं। A, B और C तीनों मिलकर वह काम कितने दिन में करेंगे?", "oh": ["60 दिन", "20 दिन", "47/3 दिन", "10 दिन"], "eh": "2(A + B + C) = 1/12 + 1/20 + 1/15 → A + B + C = 1/10 प्रति दिन → 10 दिन।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 9 consecutive even numbers is 26. What is the smallest of them?", "o": ["35", "20", "34", "18"], "a": 3, "e": "The average is the middle number 26; there are 4 numbers on each side with gap 2 → smallest = 18.", "qh": "9 लगातार सम संख्याओं का औसत 26 है। उनमें सबसे छोटी संख्या कौन-सी है?", "oh": ["35", "20", "34", "18"], "eh": "औसत ही बीच वाली संख्या 26 है; दोनों ओर 4 संख्याएँ, अंतर 2 → उत्तर = 18।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "The incomes of Anjali and Naveen are in the ratio 5 : 4 and their expenditures are in the ratio 7 : 4. If each of them saves ₹1,600, what is Anjali's income?", "o": ["₹2,400", "₹3,000", "₹1,400", "₹2,000"], "a": 1, "e": "5x − 7y = 4x − 4y = 1600 → 1x = 3y. Solving: x = 600, y = 200, so income = 5 × 600 = ₹3,000.", "qh": "अंजलि और नवीन की आय का अनुपात 5 : 4 और खर्च का अनुपात 7 : 4 है। अगर दोनों ₹1,600 बचाते हैं, तो अंजलि की आय कितनी है?", "oh": ["₹2,400", "₹3,000", "₹1,400", "₹2,000"], "eh": "5x − 7y = 4x − 4y = 1600 → 1x = 3y। हल करने पर x = 600, y = 200, आय = 5 × 600 = ₹3,000।", "level": "tough"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 40% of 440 + 20% of 630 = ?", "o": ["302", "304", "297", "312"], "a": 0, "e": "40% of 440 = 176; 20% of 630 = 126; result = 302.", "qh": "सरल कीजिए: 440 का 40% + 630 का 20% = ?", "oh": ["302", "304", "297", "312"], "eh": "440 का 40% = 176; 630 का 20% = 126; परिणाम = 302।", "level": "easy"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A bus goes from town P to town Q at 36 km/h and returns along the same road at 54 km/h. What is its average speed for the whole journey?", "o": ["45 km/h", "45.2 km/h", "43.2 km/h", "18 km/h"], "a": 2, "e": "Average speed = 2ab/(a + b) = 2 × 36 × 54/90 = 43.2 km/h.", "qh": "एक बस कस्बे P से कस्बे Q तक 36 km/h की रफ़्तार से जाती है और उसी रास्ते से 54 km/h की रफ़्तार से लौटती है। पूरे सफ़र में उसकी औसत रफ़्तार क्या है?", "oh": ["45 km/h", "45.2 km/h", "43.2 km/h", "18 km/h"], "eh": "औसत रफ़्तार = 2ab/(a + b) = 2 × 36 × 54/90 = 43.2 km/h।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nE49Z, H64W, K81T, N100Q, ?", "o": ["Q123N", "Q120N", "Q121N", "P121M"], "a": 2, "e": "First letter +3; number: consecutive squares; last letter -3. So ? = Q121N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nE49Z, H64W, K81T, N100Q, ?", "oh": ["Q123N", "Q120N", "Q121N", "P121M"], "eh": "पहला अक्षर +3; संख्या: लगातार वर्ग संख्याएँ; आखिरी अक्षर -3। इसलिए ? = Q121N।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '÷', '−' means '+', '×' means '−', '÷' means '×', then what is the value of the following expression?\n19 + 19 − 28 + 14 = ?", "o": ["3", "6", "13", "5"], "a": 0, "e": "Replace the signs: 19 ÷ 19 + 28 ÷ 14 = 3 (using BODMAS).", "qh": "अगर '+' का मतलब '÷', '−' का मतलब '+', '×' का मतलब '−', '÷' का मतलब '×' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n19 + 19 − 28 + 14 = ?", "oh": ["3", "6", "13", "5"], "eh": "चिह्न बदलें: 19 ÷ 19 + 28 ÷ 14 = 3 (BODMAS से)।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["EFG", "FGH", "DFG", "OPQ"], "a": 2, "e": "In EFG, FGH, OPQ the gaps are +1, +1; in DFG they are +2, +1.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["EFG", "FGH", "DFG", "OPQ"], "eh": "EFG, FGH, OPQ में अंतर +1, +1 है; DFG में +2, +1 है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Calendar and Clock", "q": "What is the angle between the hour hand and the minute hand of a clock at 10:15?", "o": ["132.5°", "147.5°", "210°", "142.5°"], "a": 3, "e": "Angle = |30H − 5.5M| = |30×10 − 5.5×15| = 217.5° → smaller angle = 142.5°.", "qh": "10:15 बजे घड़ी की घंटे और मिनट की सुई के बीच कितना कोण होगा?", "oh": ["132.5°", "147.5°", "210°", "142.5°"], "eh": "कोण = |30H − 5.5M| = |30×10 − 5.5×15| = 217.5° → छोटा कोण = 142.5°।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "U is the mother of A. A is the brother of C. How is U related to C?", "o": ["Niece", "Sister-in-law", "Mother", "Granddaughter"], "a": 2, "e": "Draw the family tree: U → A: mother; A → C: brother. So U is the mother of C.", "qh": "U, A की माँ है। A, C का भाई है। U का C से क्या संबंध है?", "oh": ["भतीजी/भांजी", "साली/ननद/भाभी", "माँ", "पोती/नातिन"], "eh": "परिवार का चार्ट बनाएँ: U → A: माँ; A → C: भाई। इसलिए U, C की माँ है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nPilot : Aeroplane :: Driver : ?", "o": ["Car", "Road", "Petrol", "Wheel"], "a": 0, "e": "Relation: 'operates'. Pilot – Aeroplane, so Driver – Car.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nपायलट : हवाई जहाज़ :: ड्राइवर : ?", "oh": ["कार", "सड़क", "पेट्रोल", "पहिया"], "eh": "संबंध: 'चलाता है'। पायलट – हवाई जहाज़, इसलिए ड्राइवर – कार।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '−', '−' means '×', '×' means '÷', '÷' means '+', then what is the value of the following expression?\n28 ÷ 25 ÷ 21 − 25 = ?", "o": ["578", "588", "575", "580"], "a": 0, "e": "Replace the signs: 28 + 25 + 21 × 25 = 578 (using BODMAS).", "qh": "अगर '+' का मतलब '−', '−' का मतलब '×', '×' का मतलब '÷', '÷' का मतलब '+' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n28 ÷ 25 ÷ 21 − 25 = ?", "oh": ["578", "588", "575", "580"], "eh": "चिह्न बदलें: 28 + 25 + 21 × 25 = 578 (BODMAS से)।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Statement and Conclusion", "q": "Read the statement and the conclusions/assumptions given below and decide which of them logically follow(s).\nStatement: The railway station has installed escalators on all platforms.\nConclusions:\nI. Passengers will find it easier to change platforms.\nII. Stairs at the station will be removed.", "o": ["Only conclusion II follows", "Both I and II follow", "Only conclusion I follows", "Neither I nor II follows"], "a": 2, "e": "Escalators make moving between platforms easier (I). Nothing says the stairs will go (II does not follow).", "qh": "नीचे दिए कथन और निष्कर्ष/धारणाएँ पढ़कर तय कीजिए कि कौन-सा/से तर्क के आधार पर सही है/हैं।\nकथन: रेलवे स्टेशन ने सभी प्लेटफ़ॉर्म पर एस्केलेटर लगा दिए हैं।\nनिष्कर्ष:\nI. यात्रियों को प्लेटफ़ॉर्म बदलने में आसानी होगी।\nII. स्टेशन की सीढ़ियाँ हटा दी जाएँगी।", "oh": ["केवल निष्कर्ष II सही है", "I और II दोनों सही हैं", "केवल निष्कर्ष I सही है", "न I सही है, न II"], "eh": "एस्केलेटर से आना-जाना आसान होगा (I)। सीढ़ियाँ हटाने की कोई बात नहीं (II नहीं)।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nFZQ, GDO, HHM, ILK, ?", "o": ["JOI", "JQI", "JPI", "KPI"], "a": 2, "e": "Letter positions move by +1, +4, −2 (for 1st, 2nd, 3rd letters). So ? = JPI.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nFZQ, GDO, HHM, ILK, ?", "oh": ["JOI", "JQI", "JPI", "KPI"], "eh": "अक्षरों की स्थिति +1, +4, −2 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = JPI।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "V is the father of E. E is the son of A. A is the daughter of N. N is the father of F. How is V related to F?", "o": ["Son", "Father-in-law", "Husband", "Brother-in-law"], "a": 3, "e": "Draw the family tree: V → E: father; E → A: son; A → N: daughter; N → F: father. So V is the brother-in-law of F.", "qh": "V, E का पिता है। E, A का बेटा है। A, N की बेटी है। N, F का पिता है। V का F से क्या संबंध है?", "oh": ["बेटा", "ससुर", "पति", "साला/देवर/जीजा"], "eh": "परिवार का चार्ट बनाएँ: V → E: पिता; E → A: बेटा; A → N: बेटी; N → F: पिता। इसलिए V, F का साला/देवर/जीजा है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Puzzle", "q": "6 boxes T, U, V, R, Q and P are kept one above the other (not necessarily in this order).\nBox V is neither at the top nor at the bottom.\nExactly 1 box is placed between boxes U and T.\nBox U is 6th from the bottom.\nBox U is placed immediately above box R.\nExactly 2 boxes are placed between boxes Q and R.\nBox R is neither at the top nor at the bottom.\nWhich box is immediately below box V?", "o": ["Q", "R", "P", "T"], "a": 0, "e": "Only one order fits (bottom to top): P Q V T R U. Answer: Q.", "qh": "6 डिब्बे T, U, V, R, Q और P एक के ऊपर एक रखे हैं (ज़रूरी नहीं कि इसी क्रम में)।\nडिब्बा V न सबसे ऊपर है, न सबसे नीचे।\nडिब्बे U और T के बीच ठीक 1 डिब्बे रखे हैं।\nडिब्बा U नीचे से 6वें स्थान पर है।\nडिब्बा U, डिब्बे R के ठीक ऊपर रखा है।\nडिब्बे Q और R के बीच ठीक 2 डिब्बे रखे हैं।\nडिब्बा R न सबसे ऊपर है, न सबसे नीचे।\nडिब्बे V के ठीक नीचे कौन-सा डिब्बा है?", "oh": ["Q", "R", "P", "T"], "eh": "केवल एक क्रम बैठता है (नीचे से ऊपर): P Q V T R U। उत्तर: Q।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Suresh starts from point P, walks 10 km towards West, then turns left and walks 6 km, then turns left and walks 5 km. In which direction is Suresh now with respect to point P?", "o": ["North-East", "South-West", "South", "South-East"], "a": 1, "e": "Net East–West = -5 km, net North–South = -6 km; direction = South-West.", "qh": "सुरेश बिंदु P से शुरू करके पश्चिम की ओर 10 km चलता है, फिर बाएँ मुड़कर 6 km चलता है, फिर बाएँ मुड़कर 5 km चलता है। अब सुरेश बिंदु P से किस दिशा में है?", "oh": ["उत्तर-पूर्व", "दक्षिण-पश्चिम", "दक्षिण", "दक्षिण-पूर्व"], "eh": "कुल पूर्व–पश्चिम = -5 km, कुल उत्तर–दक्षिण = -6 km; दिशा = दक्षिण-पश्चिम।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nGOY : KMW :: RXC : ?", "o": ["AVV", "VVA", "NZE", "VVB"], "a": 1, "e": "Each letter moves +4, -2, -2 in order. RXC → VVA.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nGOY : KMW :: RXC : ?", "oh": ["AVV", "VVA", "NZE", "VVB"], "eh": "हर अक्षर क्रम से +4, -2, -2 खिसकता है। RXC → VVA।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language:\n'long city green' is written as 'dy mo ze',\n'clean long cold' is written as 'ta lo dy',\n'city sun clean' is written as 'lo mo gu',\nWhat is the code for 'city'?", "o": ["mo", "dy", "ze", "lo"], "a": 0, "e": "Compare the sentences: common words and common codes match. This gives 'city' = 'mo'.", "qh": "एक कोड भाषा में:\n'long city green' को 'dy mo ze' लिखा जाता है,\n'clean long cold' को 'ta lo dy' लिखा जाता है,\n'city sun clean' को 'lo mo gu' लिखा जाता है,\n'city' का कोड क्या है?", "oh": ["mo", "dy", "ze", "lo"], "eh": "वाक्यों की तुलना करें: साझा शब्द और साझा कोड आपस में मिलते हैं। इससे 'city' = 'mo' मिलता है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Deepak starts from point P, walks 4 km towards South, then turns left and walks 3 km, then turns left and walks 15 km, then turns left and walks 6 km. In which direction is Deepak now with respect to point P?", "o": ["South-East", "North-West", "South", "East"], "a": 1, "e": "Net East–West = -3 km, net North–South = +11 km; direction = North-West.", "qh": "दीपक बिंदु P से शुरू करके दक्षिण की ओर 4 km चलता है, फिर बाएँ मुड़कर 3 km चलता है, फिर बाएँ मुड़कर 15 km चलता है, फिर बाएँ मुड़कर 6 km चलता है। अब दीपक बिंदु P से किस दिशा में है?", "oh": ["दक्षिण-पूर्व", "उत्तर-पश्चिम", "दक्षिण", "पूर्व"], "eh": "कुल पूर्व–पश्चिम = -3 km, कुल उत्तर–दक्षिण = +11 km; दिशा = उत्तर-पश्चिम।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["6 – 36", "8 – 65", "11 – 121", "3 – 9"], "a": 1, "e": "In all except 8 – 65: second number is the square of the first.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["6 – 36", "8 – 65", "11 – 121", "3 – 9"], "eh": "8 – 65 को छोड़कर सभी में: दूसरी संख्या पहली का वर्ग है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nDG, GJ, JM, MP, ?", "o": ["OS", "PT", "PU", "PS"], "a": 3, "e": "Letter positions move by +3, +3 (for 1st, 2nd letters). So ? = PS.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nDG, GJ, JM, MP, ?", "oh": ["OS", "PT", "PU", "PS"], "eh": "अक्षरों की स्थिति +3, +3 से बदलती है (पहले, दूसरे अक्षर के लिए)। इसलिए ? = PS।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nNo birds are shoes.\nAll shoes are plates.\nConclusions:\nI. Some plates are birds.\nII. All plates are birds.", "o": ["Neither I nor II follows", "Only conclusion I follows", "Both I and II follow", "Only conclusion II follows"], "a": 0, "e": "Each conclusion fails in at least one possible diagram, and they do not form an either–or pair.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकोई भी पक्षी जूते नहीं है।\nसभी जूते प्लेटें हैं।\nनिष्कर्ष:\nI. कुछ प्लेटें पक्षी हैं।\nII. सभी प्लेटें पक्षी हैं।", "oh": ["न I सही है, न II", "केवल निष्कर्ष I सही है", "I और II दोनों सही हैं", "केवल निष्कर्ष II सही है"], "eh": "हर निष्कर्ष किसी न किसी आरेख में गलत हो जाता है, और ये 'या तो–या' वाली जोड़ी नहीं हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n11 : 1331 :: 3 : ?", "o": ["33", "27", "30", "9"], "a": 1, "e": "Rule: x → x³. 11 → 1331, so 3 → 27.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n11 : 1331 :: 3 : ?", "oh": ["33", "27", "30", "9"], "eh": "नियम: x → x³। 11 → 1331, इसलिए 3 → 27।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Kabaddi", "Kho-kho", "Hockey", "Chess"], "a": 3, "e": "Chess is an indoor board game; the others are field games.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["कबड्डी", "खो-खो", "हॉकी", "शतरंज"], "eh": "शतरंज बोर्ड पर खेला जाने वाला इनडोर खेल है; बाकी मैदान के खेल हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n3 8 C F * L # 5 * 6 S F $ * + $ * © 9 8 4 #\nHow many odd numbers are there in the arrangement, each of which is immediately preceded by a symbol?", "o": ["3", "2", "5", "1"], "a": 1, "e": "Matching places: #5*, ©98 → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n3 8 C F * L # 5 * 6 S F $ * + $ * © 9 8 4 #\nइस क्रम में ऐसी कितनी विषम संख्याएँ हैं, जिनके ठीक पहले एक चिह्न है?", "oh": ["3", "2", "5", "1"], "eh": "शर्त पूरी करने वाले स्थान: #5*, ©98 → 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n65, 124, 217, 342, 513, ?", "o": ["729", "733", "728", "727"], "a": 2, "e": "Rule: n³ + 1, n³ − 1 alternately for n = 4, 5, … So ? = 728.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n65, 124, 217, 342, 513, ?", "oh": ["729", "733", "728", "727"], "eh": "नियम: n³ + 1 और n³ − 1 बारी-बारी से, n = 4, 5, … इसलिए ? = 728।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "K, J, G, U, P, R and H are sitting in a row, all facing North.\nH sits second to the right of K.\nExactly 4 persons sit between H and P.\nU and H sit next to each other.\nExactly 2 persons sit between R and H.\nExactly 2 persons sit between U and G.\nExactly 4 persons sit between J and U.\nR does not sit at either end.\nHow many persons sit between H and J?", "o": ["6", "5", "8", "4"], "a": 1, "e": "Only one order fits all clues (left to right): J P G R K U H. Answer: 5.", "qh": "K, J, G, U, P, R और H एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nH, K के दाईं ओर दूसरे स्थान पर बैठा है।\nH और P के बीच ठीक 4 व्यक्ति बैठे हैं।\nU और H पास-पास बैठे हैं।\nR और H के बीच ठीक 2 व्यक्ति बैठे हैं।\nU और G के बीच ठीक 2 व्यक्ति बैठे हैं।\nJ और U के बीच ठीक 4 व्यक्ति बैठे हैं।\nR किसी भी छोर पर नहीं बैठा है।\nH और J के बीच कितने व्यक्ति बैठे हैं?", "oh": ["6", "5", "8", "4"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): J P G R K U H। उत्तर: 5।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "K, C, Q, H, A and V are sitting around a circular table, all facing the centre.\nQ is not an immediate neighbour of A.\nK sits second to the right of A.\nK sits second to the left of C.\nK is an immediate neighbour of H.\nWho sits second to the left of V?", "o": ["C", "Q", "A", "K"], "a": 1, "e": "Only one arrangement fits. Going to the right (anticlockwise) from V: V → A → H → K → Q → C. Answer: Q.", "qh": "K, C, Q, H, A और V एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nQ, A का ठीक पड़ोसी नहीं है।\nK, A के दाईं ओर दूसरे स्थान पर बैठा है।\nK, C के बाईं ओर दूसरे स्थान पर बैठा है।\nK, H का ठीक पड़ोसी है।\nV के बाईं ओर दूसरे स्थान पर कौन बैठा है?", "oh": ["C", "Q", "A", "K"], "eh": "केवल एक व्यवस्था बैठती है। V से दाईं ओर (घड़ी की उलटी दिशा में) चलें: V → A → H → K → Q → C। उत्तर: Q।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of 32 children, Manoj is 9th from the left and Karan is 20th from the right. When Manoj shifts 5 places towards the right, what is his position from the right end?", "o": ["21", "20", "19", "18"], "a": 2, "e": "New position from left = 9 + 5 = 14; from right = 32 − 14 + 1 = 19.", "qh": "32 बच्चों की पंक्ति में मनोज बाएँ से 9वें और करण दाएँ से 20वें स्थान पर है। मनोज के 5 स्थान दाईं ओर खिसकने पर वह दाएँ छोर से किस स्थान पर होगा?", "oh": ["21", "20", "19", "18"], "eh": "बाएँ से नया स्थान = 9 + 5 = 14; दाएँ से = 32 − 14 + 1 = 19।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n$ P 4 7 P 8 H 6 8 J 2 6 & 4 9 P & 1\nHow many numbers are there in the arrangement, each of which is immediately followed by a letter?", "o": ["4", "3", "7", "6"], "a": 0, "e": "Matching places: 47P, P8H, 68J, 49P → 4.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n$ P 4 7 P 8 H 6 8 J 2 6 & 4 9 P & 1\nइस क्रम में ऐसी कितनी संख्याएँ हैं, जिनके ठीक बाद एक अक्षर है?", "oh": ["4", "3", "7", "6"], "eh": "शर्त पूरी करने वाले स्थान: 47P, P8H, 68J, 49P → 4।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'TOWER' is coded as 397. How will 'SUGAR' be coded in that language?", "o": ["323", "322", "327", "66"], "a": 1, "e": "Code = (sum of letter positions) × (number of letters) − 8. For SUGAR: 322.", "qh": "एक कोड भाषा में 'TOWER' को 397 लिखा जाता है। उसी भाषा में 'SUGAR' को कैसे लिखा जाएगा?", "oh": ["323", "322", "327", "66"], "eh": "कोड = (अक्षरों की स्थितियों का योग) × (अक्षरों की संख्या) − 8। SUGAR के लिए: 322।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n7 2 8 2 6 4 1 5 3 2 4 7 5 6 4 1 5 1 5 6 9 2 8 8 1\nHow many 5s are there, each of which is immediately preceded by an odd digit and immediately followed by an even digit?", "o": ["5", "1", "2", "4"], "a": 2, "e": "Matching groups: 7 5 6, 1 5 6 → 2.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n7 2 8 2 6 4 1 5 3 2 4 7 5 6 4 1 5 1 5 6 9 2 8 8 1\nऐसे कितने 5 हैं, जिनके ठीक पहले विषम अंक और ठीक बाद सम अंक है?", "oh": ["5", "1", "2", "4"], "eh": "शर्त पूरी करने वाले समूह: 7 5 6, 1 5 6 → 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mirror Image", "q": "Which of the following words has all its letters looking the same in a mirror image (mirror placed to the right)? (Capital letters.)", "o": ["DICE", "DECIDE", "TIMID", "YOUTH"], "a": 3, "e": "In a side mirror, letters A, H, I, M, O, T, U, V, W, X, Y look the same. Every letter of YOUTH is from this group.", "qh": "नीचे दिए शब्दों में से किस शब्द के सभी अक्षर दर्पण प्रतिबिंब (दर्पण दाईं ओर रखा हो) में वैसे ही दिखेंगे? (बड़े अंग्रेज़ी अक्षर।)", "oh": ["DICE", "DECIDE", "TIMID", "YOUTH"], "eh": "बगल के दर्पण में A, H, I, M, O, T, U, V, W, X, Y वैसे ही दिखते हैं। YOUTH के सारे अक्षर इसी समूह के हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n789   389   172   976   273\nIf 1 is added to each digit of every number (9 becomes 0), how many of the new numbers will be even?", "o": ["4", "3", "1", "5"], "a": 1, "e": "New numbers: 890, 490, 283, 87, 384 → even ones = 3.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n789   389   172   976   273\nअगर हर संख्या के हर अंक में 1 जोड़ा जाए (9 का 0 हो जाए), तो नई संख्याओं में से कितनी सम होंगी?", "oh": ["4", "3", "1", "5"], "eh": "नई संख्याएँ: 890, 490, 283, 87, 384 → सम संख्याएँ = 3।", "level": "medium"}]});
